<script setup lang="ts">
import { onMounted, ref } from 'vue';import { useRoute,useRouter } from 'vue-router';import { api,type SkillDetail } from '../api'
const route=useRoute(),router=useRouter(),detail=ref<SkillDetail>(),loading=ref(true),error=ref(''),scope=ref<'PERSONAL'|'PROJECT'>('PERSONAL'),projectRef=ref('')
onMounted(async()=>{try{detail.value=await api.detail(String(route.params.slug))}catch(e){error.value=e instanceof Error?e.message:'Skill unavailable.'}finally{loading.value=false}})
async function install(){if(!detail.value)return;try{const r=await api.createOperation(crypto.randomUUID(),{operationType:'INSTALL',skillId:detail.value.skill.id,hostCode:'VSCODE_COPILOT_CHAT',scope:{type:scope.value,projectRef:scope.value==='PROJECT'?projectRef.value:null},targetVersion:detail.value.versions[0]?.semanticVersion});await router.push(`/operations/${r.operationId}`)}catch(e){error.value=e instanceof Error?e.message:'Install request failed.'}}
</script>
<template><section class="shell"><p v-if="loading" role="status">Loading Skill…</p><div v-else-if="error" class="error" role="alert">{{error}}</div><template v-else-if="detail"><RouterLink to="/discover">← Back to Discover</RouterLink><div class="hero"><div class="eyebrow">{{detail.skill.category.label}}</div><h1>{{detail.skill.displayName}}</h1><p class="muted">{{detail.skill.description}}</p><div class="tags"><span class="tag">Owner: {{detail.skill.ownerDisplayName}}</span><span :class="['tag','status',detail.skill.certificationState]">{{detail.skill.certificationState}}</span></div></div><div class="grid"><article class="panel"><h2>Curated example report</h2><p class="muted">{{detail.curatedReport}}</p><h2>Published versions</h2><div v-for="v in detail.versions" :key="v.id"><strong>{{v.semanticVersion}}</strong> · {{v.certificationState}}<p class="muted">{{v.changelog}}</p></div></article><aside class="panel"><h2>Install Skill</h2><p class="muted">Local mode uses a deterministic adapter and does not write files.</p><label><input v-model="scope" type="radio" value="PERSONAL"> Personal</label><label><input v-model="scope" type="radio" value="PROJECT"> Project</label><label v-if="scope==='PROJECT'">Project reference<input v-model="projectRef" class="field" required></label><button class="button primary" type="button" @click="install">Confirm install</button></aside></div></template></section></template>
<style scoped>aside label{display:block;margin:1rem 0}</style>
